parameters.functionCode:
const codeToReview = $json["code"];

// Simulate AI code review process
const reviewComments = [];

if (codeToReview.includes("eval")) {
  reviewComments.push("Avoid using 'eval' for security reasons.");
}
if (codeToReview.length > 500) {
  reviewComments.push("Consider breaking down the code into smaller functions for better readability.");
}

return [{ json: { comments: reviewComments } }];
